"""RoboPaint episode controller. All motion uses the public Robot client.
Jobs and action arrays are retained alongside this script for replay/audit.
"""
import sys, os, json, time, traceback
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=Path('/app/output');r=Robot();spec=r.spec();Q=[0.,1.,0.,0.]
seq=0

def saveobs(o,name):
    (ROOT/(name+'_meta.json')).write_text(json.dumps(o.meta,indent=1))
    for c,a in o.last.items():Image.fromarray(a).save(ROOT/(name+'_'+c+'.png'))
    if o.proprio is not None:np.save(ROOT/(name+'_proprio.npy'),o.proprio)

def send(a,note='',cams=['practice_cam'],fps=10):
    global seq,last
    a=np.asarray(a,float);seq+=1
    np.save(ROOT/f'actions_{seq:04}.npy',a)
    last=r.submit('ee_pose',a,dt=.05,cameras=cams,video='none',video_fps=fps,note=note)
    saveobs(last,f'call_{seq:04}')
    print('CALL',seq,last.meta.get('control_steps'),last.meta.get('plan'),flush=True)
    if last.stopped:raise RuntimeError('partial execution')
    return last

def pose(x,y,z):return [x,y,z]+Q

def line(a,b,speed=.03):
    n=max(1,int(np.ceil(np.linalg.norm(np.array(b[:3])-a[:3])/(speed*.05))))
    return np.linspace(a,b,n+1)[1:].tolist()

def move(x,y,z,speed=.04):
    o=r.get_obs(cameras=[]);a=list(o.group('tcp_pose',now=True)); b=pose(x,y,z)
    path=line(a,b,speed)+[b]*8
    for i in range(0,len(path),190):send(path[i:i+190], 'air move')

if __name__=='__main__':
    print('READY',flush=True)
    jobs=ROOT/'jobs';jobs.mkdir(exist_ok=True)
    while True:
        for f in sorted(jobs.glob('*.py')):
            done=f.with_suffix('.done')
            if done.exists():continue
            try:
                exec(compile(f.read_text(),str(f),'exec'),globals())
                done.write_text('ok')
            except Exception:
                done.write_text(traceback.format_exc());traceback.print_exc()
        time.sleep(.2)
PY
